arguments.command:
cd /workspace && cat > /tmp/runex.py <<'EOF'
import json, subprocess, sys
fixtures = json.load(open('/workspace/examples/checks.json'))
for f in fixtures:
    p = subprocess.run([sys.executable, '/workspace/run.py'], input=f['input'].encode(), capture_output=True)
    out = p.stdout.decode()
    try:
        resp = json.loads(out)
    except Exception as e:
        print(f['name'], 'PARSE FAIL', out[:200], p.stderr.decode()[:400]); continue
    if f.get('invalid'):
        ok = resp == {'error':'invalid'}
        print(('PASS' if ok else 'FAIL'), f['name'], resp if not ok else '')
        continue
    exp = f['expected']
    ok = len(resp.get('results',[])) == len(exp)
    if ok:
        for r, e in zip(resp['results'], exp):
            if r['answers'] != e['answers']: ok=False; print('  answers', r['answers'], 'want', e['answers'])
            if r['loads'] != e['loads']: ok=False; print('  loads', r['loads'], 'want', e['loads'])
            if len(r['snapshots']) != e['snapshots']: ok=False; print('  snapshots', len(r['snapshots']))
    print(('PASS' if ok else 'FAIL'), f['name'])
EOF
python3 /tmp/runex.py
